using Microsoft.AspNetCore.Components;
using pax.chess;
using System.Text;

namespace pax.BlazorChess.Shared.Components;

public partial class ClockComponent : ComponentBase, IChessClockDisplay
{
    private TimeSpan _whiteTime;
    private TimeSpan _blackTime;
    private PieceColor? _activeColor;
    private PieceColor? _timedOutColor;

    public void OnClockUpdated(TimeSpan whiteTime, TimeSpan blackTime, PieceColor? activeColor)
    {
        _whiteTime = whiteTime;
        _blackTime = blackTime;
        _activeColor = activeColor;
        InvokeAsync(StateHasChanged);
    }

