    }

    private string GetCssClass(PieceColor color)
    {
        bool isActive = _activeColor == color;
        bool isTimedOut = _timedOutColor == color;
        bool isShortOnTime = (color == PieceColor.White && _whiteTime.TotalSeconds < 30) ||
                        (color == PieceColor.Black && _blackTime.TotalSeconds < 30);
        StringBuilder sb = new();
        sb.Append(color == PieceColor.White ? "clock white" : "clock black");
        if (isActive)
            sb.Append(" active");
        if (isTimedOut)
            sb.Append(" timed-out");
        else if (isShortOnTime)
            sb.Append(" short-on-time");
        return sb.ToString();
